-- ============================================================
-- Yu Picture Community Feature V1
-- Target: yu-picture-backend (ordinary layered backend)
-- Default database: yu_picture
-- IMPORTANT:
-- 1) Back up and test against a development database first.
-- 2) Verify MySQL version, actual datasource name and ShardingSphere
--    routing rules before deployment.
-- 3) No foreign keys are declared intentionally; existing tables may be
--    sharded and referential/permission checks belong to Service layer.
-- 4) New entity IDs are expected to be generated by MyBatis-Plus ASSIGN_ID.
-- ============================================================

USE yu_picture;

-- 1. Community post
CREATE TABLE IF NOT EXISTS community_post
(
    id                       BIGINT       NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    userId                   BIGINT       NOT NULL COMMENT '实际发帖用户 id，关联 user.id',
    postType                 TINYINT      NOT NULL COMMENT '帖子类型：1-分享帖 2-求助帖',
    publishType              TINYINT      NOT NULL COMMENT '发布身份：1-个人 2-团队',
    publishSpaceId            BIGINT       NULL COMMENT '团队发布时的空间 id，关联 space.id',
    publishUserNameSnapshot   VARCHAR(256) NOT NULL COMMENT '发布时个人昵称快照',
    publishSpaceNameSnapshot  VARCHAR(128) NULL COMMENT '发布时团队名称快照',
    publishRoleSnapshot       VARCHAR(32)  NULL COMMENT '发布时团队角色快照：viewer/editor/admin',
    title                    VARCHAR(128) NOT NULL COMMENT '帖子标题',
    content                  TEXT         NOT NULL COMMENT '帖子正文',
    categoryId               BIGINT       NOT NULL COMMENT '社区主分类 id',
    status                   TINYINT      NOT NULL DEFAULT 0 COMMENT '状态：0-待审核 1-已发布 2-已拒绝 3-已下架',
    likeCount                BIGINT       NOT NULL DEFAULT 0 COMMENT '帖子点赞数冗余统计',
    commentCount             BIGINT       NOT NULL DEFAULT 0 COMMENT '帖子评论数冗余统计',
    createTime               DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    editTime                 DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '编辑时间',
    updateTime               DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    isDelete                 TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-否 1-是',
    PRIMARY KEY (id),
    KEY idx_status_delete_create (status, isDelete, createTime, id),
    KEY idx_category_status_create (categoryId, status, isDelete, createTime, id),
    KEY idx_user_create (userId, isDelete, createTime, id),
    KEY idx_publish_space (publishSpaceId, isDelete, createTime, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区帖子';

-- 2. Community public image resources. These are NOT rows in picture by default.
CREATE TABLE IF NOT EXISTS community_image
(
    id                    BIGINT        NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    ownerUserId           BIGINT        NOT NULL COMMENT '创建/上传该社区图片的用户 id',
    sourceType            TINYINT       NOT NULL COMMENT '来源：1-选择现有图库图片 2-新上传',
    sourcePictureId       BIGINT        NULL COMMENT '选择现有图库图片时的源 picture.id',
    savedPictureId        BIGINT        NULL COMMENT '新上传图片同时存入空间时的 picture.id',
    name                  VARCHAR(128)  NOT NULL COMMENT '图片名称',
    url                   VARCHAR(1024) NOT NULL COMMENT '社区公开副本 URL',
    thumbnailUrl          VARCHAR(1024) NULL COMMENT '社区公开副本缩略图 URL',
    storageKey            VARCHAR(512)  NOT NULL COMMENT '社区公开副本 COS object key',
    thumbnailStorageKey   VARCHAR(512)  NULL COMMENT '社区缩略图 COS object key',
    picSize               BIGINT        NULL COMMENT '图片大小（字节）',
    picWidth              INT           NULL COMMENT '图片宽度',
    picHeight             INT           NULL COMMENT '图片高度',
    picFormat             VARCHAR(32)   NULL COMMENT '图片格式',
    reviewStatus          TINYINT       NOT NULL DEFAULT 0 COMMENT '审核状态：0-待审核 1-通过 2-拒绝',
    reviewMessage         VARCHAR(512)  NULL COMMENT '审核意见',
    reviewerId            BIGINT        NULL COMMENT '审核人 user.id',
    reviewTime            DATETIME      NULL COMMENT '审核时间',
    createTime            DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updateTime            DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    isDelete              TINYINT       NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-否 1-是',
    PRIMARY KEY (id),
    KEY idx_owner_create (ownerUserId, isDelete, createTime, id),
    KEY idx_source_picture (sourcePictureId),
    KEY idx_saved_picture (savedPictureId),
    KEY idx_review_queue (reviewStatus, isDelete, createTime, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区公开图片资源';

-- 3. Post-image relation. One community image can be reused by more than one post.
CREATE TABLE IF NOT EXISTS community_post_image
(
    id                BIGINT   NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    postId            BIGINT   NOT NULL COMMENT 'community_post.id',
    communityImageId  BIGINT   NOT NULL COMMENT 'community_image.id',
    sortOrder         INT      NOT NULL DEFAULT 0 COMMENT '图片展示顺序',
    createTime        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_post_image (postId, communityImageId),
    KEY idx_image_post (communityImageId, postId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='帖子与社区图片关联';

-- 4. Community comments and one-level replies.
CREATE TABLE IF NOT EXISTS community_comment
(
    id             BIGINT        NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    postId         BIGINT        NOT NULL COMMENT 'community_post.id',
    userId         BIGINT        NOT NULL COMMENT '评论用户 id',
    parentId       BIGINT        NULL COMMENT '顶层评论 id；为空表示顶层评论',
    replyToUserId  BIGINT        NULL COMMENT '被回复的用户 id',
    content        VARCHAR(2000) NOT NULL COMMENT '评论内容',
    status         TINYINT       NOT NULL DEFAULT 1 COMMENT '状态：1-正常 2-隐藏',
    createTime     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updateTime     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    isDelete       TINYINT       NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-否 1-是',
    PRIMARY KEY (id),
    KEY idx_post_comment_time (postId, isDelete, status, createTime, id),
    KEY idx_parent_comment_time (parentId, isDelete, status, createTime, id),
    KEY idx_user_comment_time (userId, isDelete, createTime, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区评论';

-- 5. Post likes. Unique key makes the relation idempotent.
CREATE TABLE IF NOT EXISTS community_post_like
(
    id         BIGINT   NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    postId     BIGINT   NOT NULL COMMENT 'community_post.id',
    userId     BIGINT   NOT NULL COMMENT '点赞用户 id',
    createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_post_user (postId, userId),
    KEY idx_user_time (userId, createTime, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区帖子点赞';

-- 6. Public gallery picture likes; service must verify picture.spaceId IS NULL,
--    picture.reviewStatus = 1 and picture.isDelete = 0 before insert.
CREATE TABLE IF NOT EXISTS picture_like
(
    id         BIGINT   NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    pictureId  BIGINT   NOT NULL COMMENT '公共图库图片 picture.id',
    userId     BIGINT   NOT NULL COMMENT '点赞用户 id',
    createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_picture_user (pictureId, userId),
    KEY idx_user_time (userId, createTime, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公共图库图片点赞';

-- 7. Community categories (one primary category per post).
CREATE TABLE IF NOT EXISTS community_category
(
    id          BIGINT       NOT NULL COMMENT 'id',
    categoryName VARCHAR(64)  NOT NULL COMMENT '分类名称',
    description VARCHAR(256) NULL COMMENT '分类说明',
    sortOrder   INT          NOT NULL DEFAULT 0 COMMENT '排序值',
    status      TINYINT      NOT NULL DEFAULT 1 COMMENT '状态：1-启用 0-停用',
    createTime  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updateTime  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    isDelete    TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-否 1-是',
    PRIMARY KEY (id),
    UNIQUE KEY uk_category_name (categoryName),
    KEY idx_status_sort (status, isDelete, sortOrder, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区分类';

-- 8. Community tags.
CREATE TABLE IF NOT EXISTS community_tag
(
    id          BIGINT      NOT NULL COMMENT 'id',
    tagName     VARCHAR(64) NOT NULL COMMENT '标签名称（服务端 trim 后存储）',
    useCount    BIGINT      NOT NULL DEFAULT 0 COMMENT '使用次数冗余统计，可后续启用',
    status      TINYINT     NOT NULL DEFAULT 1 COMMENT '状态：1-启用 0-停用',
    createTime  DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updateTime  DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    isDelete    TINYINT     NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-否 1-是',
    PRIMARY KEY (id),
    UNIQUE KEY uk_tag_name (tagName),
    KEY idx_status_name (status, isDelete, tagName)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区标签';

-- 9. Post-tag relation.
CREATE TABLE IF NOT EXISTS community_post_tag
(
    id         BIGINT   NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    postId     BIGINT   NOT NULL COMMENT 'community_post.id',
    tagId      BIGINT   NOT NULL COMMENT 'community_tag.id',
    createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_post_tag (postId, tagId),
    KEY idx_tag_post (tagId, postId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='帖子标签关系';

-- 10. One community profile per user. userId is the primary key to support row locking.
CREATE TABLE IF NOT EXISTS user_community_profile
(
    userId            BIGINT   NOT NULL COMMENT 'user.id，同时作为主键',
    experience        BIGINT   NOT NULL DEFAULT 0 COMMENT '当前累计经验值',
    level             INT      NOT NULL DEFAULT 1 COMMENT '当前等级，由服务端根据经验阈值计算',
    postCount         BIGINT   NOT NULL DEFAULT 0 COMMENT '有效帖子数统计',
    commentCount      BIGINT   NOT NULL DEFAULT 0 COMMENT '有效评论数统计',
    receivedLikeCount BIGINT   NOT NULL DEFAULT 0 COMMENT '帖子收到的点赞数统计',
    createTime        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updateTime        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (userId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户社区档案与等级';

-- 11. Experience ledger. eventKey is globally unique and used for idempotency.
CREATE TABLE IF NOT EXISTS user_exp_record
(
    id            BIGINT        NOT NULL COMMENT 'id (MyBatis-Plus ASSIGN_ID)',
    userId        BIGINT        NOT NULL COMMENT '经验归属用户 id',
    eventType     TINYINT       NOT NULL COMMENT '事件类型：1-发帖 2-评论 3-获赞 4-经验撤销',
    eventKey      VARCHAR(191)  NOT NULL COMMENT '幂等业务键，全局唯一',
    changeExp     BIGINT        NOT NULL COMMENT '经验变化，正数增加，负数扣减',
    eventDate     DATE          NOT NULL COMMENT '业务发生日期，用于每日限额统计',
    sourcePostId  BIGINT        NULL COMMENT '来源帖子 id',
    sourceCommentId BIGINT      NULL COMMENT '来源评论 id',
    sourceUserId  BIGINT        NULL COMMENT '触发获赞的点赞用户 id（仅获赞奖励）',
    description   VARCHAR(256)  NULL COMMENT '经验变化说明',
    createTime    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '流水创建时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_event_key (eventKey),
    KEY idx_user_type_date (userId, eventType, eventDate),
    KEY idx_source_post (sourcePostId),
    KEY idx_source_comment (sourceCommentId)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户社区经验流水';

-- Suggested initial categories. Change names/IDs before first production deployment if needed.
INSERT IGNORE INTO community_category (id, categoryName, description, sortOrder, status)
VALUES
